import type { TechnologyInput } from "@/lib/schema";
import type { EvidenceGrade } from "@/lib/complementary";
import type { ComplementaryEntry } from "./complementary";

/**
 * Complementary and alternative products, gap round November 2026, part two: vitamins, minerals, amino acids,
 * hormone-like herbs, joint products and mineral 'cures' from Memorial Sloan Kettering's About Herbs database
 * that had no graded record (gap census docs/proposals/gap-census-2026-11.md, type
 * `complementary-alternative`). Products that already have a record (vitamin D and omega-3, high-dose
 * vitamin C, nicotinamide, soy) are linked rather than duplicated. Same rules as src/data/complementary.ts: a grade tag
 * `evidence:<grade>`, a number only where the linked source states it, interactions and harms taken from MSK's
 * page or the NCI PDQ summary, and no claim of benefit the evidence does not carry. MSK is summarised in our own
 * words and quoted only briefly with attribution. Each MSK page was read as raw text on the asOf date; its own
 * "last updated" date is given in the link label so a reader can see how current it is.
 *
 * Records are spread into `complementary` and their index rows into COMPLEMENTARY_INDEX in complementary.ts,
 * so the hub at /live/complementary/ and the complementary tests cover them.
 */

const asOf = "2026-11-04";
const pdq = (label: string, slug: string) => ({ label: `NCI PDQ: ${label}`, url: `https://www.cancer.gov/about-cancer/treatment/cam/hp/${slug}-pdq` });
const herbs = (label: string, slug: string) => ({ label: `MSK About Herbs: ${label}`, url: `https://www.mskcc.org/cancer-care/integrative-medicine/herbs/${slug}` });
const SEC = "supportive-care";
const T = (grade: EvidenceGrade, extra: string[] = []) => ["complementary", "supportive-care", `evidence:${grade}`, ...extra];
const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });

const SUPP = ["integrative-oncology", "dietary-supplements-treatment-interactions"];

